@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg-base: #0F0F0F;
  --bg-surface: #1E1E1E;
  --bg-surface-hover: #2A2A2A;
  --bg-surface-active: #333333;

  --brand-primary: #2962FF;
  --brand-primary-hover: #1E4BD8;

  --text-primary: #F0F0F0;
  --text-secondary: #A0A0A0;
  --text-tertiary: #6B6B6B;

  --status-positive: #089981;
  --status-positive-bg: rgba(8, 153, 129, 0.15);
  --status-negative: #F7525F;
  --status-negative-bg: rgba(247, 82, 95, 0.15);

  --border-light: #2A2E39;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-base);
  color: var(--text-primary);
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--bg-base); 
}
::-webkit-scrollbar-thumb {
  background: var(--bg-surface-hover); 
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-tertiary); 
}

/* Utilities */
.text-positive { color: var(--status-positive); }
.text-negative { color: var(--status-negative); }
.bg-positive-subtle { background-color: var(--status-positive-bg); }
.bg-negative-subtle { background-color: var(--status-negative-bg); }

.bg-surface { background-color: var(--bg-surface); }
.bg-base { background-color: var(--bg-base); }
.border-light { border-color: var(--border-light); }
.text-primary { color: var(--text-primary); }
.text-secondary { color: var(--text-secondary); }
.brand-primary { background-color: var(--brand-primary); }

/* Tabs */
.tab-btn {
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all 0.2s ease;
}
.tab-btn:hover {
  color: var(--text-primary);
}
.tab-btn.active {
  color: var(--brand-primary);
  border-bottom-color: var(--brand-primary);
}
.tab-content {
  display: none;
}
.tab-content.active {
  display: block;
}

/* Accordion */
.accordion-content {
  display: none;
}
.accordion-content.open {
  display: block;
}
.accordion-icon {
  transition: transform 0.2s ease;
}
.accordion-btn[aria-expanded="true"] .accordion-icon {
  transform: rotate(180deg);
}

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
}
th {
  text-align: left;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-light);
  font-size: 12px;
}
td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-light);
  font-size: 14px;
}
tr:hover td {
  background-color: var(--bg-surface-hover);
}
tr:last-child td {
  border-bottom: none;
}

/* Sparkline */
.sparkline {
  width: 60px;
  height: 20px;
}
.sparkline-positive {
  stroke: var(--status-positive);
}
.sparkline-negative {
  stroke: var(--status-negative);
}

document.addEventListener('DOMContentLoaded', () => {
  // Tabs
  document.querySelectorAll('.tab-group').forEach(group => {
    const buttons = group.querySelectorAll('.tab-btn');
    const contents = document.querySelectorAll(group.dataset.targetContent || '.tab-content');

    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        // Deactivate all in group
        buttons.forEach(b => {
          b.classList.remove('active');
          b.setAttribute('aria-selected', 'false');
        });

        // Deactivate all targets linked to this group
        const targetClass = group.dataset.targetClass;
        if (targetClass) {
          document.querySelectorAll(`.${targetClass}`).forEach(c => c.classList.remove('active'));
        }

        // Activate clicked
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');

        const targetId = btn.dataset.target;
        if (targetId) {
          const targetEl = document.getElementById(targetId);
          if (targetEl) {
            targetEl.classList.add('active');
          }
        }
      });
    });
  });

  // Accordions
  document.querySelectorAll('.accordion-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const expanded = btn.getAttribute('aria-expanded') === 'true' || false;
      btn.setAttribute('aria-expanded', !expanded);
      const targetId = btn.dataset.target;
      if (targetId) {
        const targetEl = document.getElementById(targetId);
        if (targetEl) {
          targetEl.classList.toggle('open');
        }
      }
    });
  });

  // Toggle buttons
  document.querySelectorAll('.toggle-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const activeClass = btn.dataset.activeClass || 'active';
      btn.classList.toggle(activeClass);

      const targetId = btn.dataset.target;
      if (targetId) {
        const targetEl = document.getElementById(targetId);
        if (targetEl) {
          targetEl.classList.toggle('active');
        }
      }
    });
  });
});
